mapper.select:
SELECT TO_CHAR(U.REG_DATE, 'YYYY-MM-DD HH24:MI:SS') AS regDate, TO_CHAR(U.UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS') AS updateDate, U.USER_NO AS userNo, U.ENABLED AS enabled, U.ROLE AS role, U.PROVIDER AS provider, U.ID AS id, U.EMAIL AS email, U.NICKNAME AS nickname, U.DESCRIPTION AS note, U.PROFILE_IMG_PATH AS profileUrl FROM MB_USER U WHERE TO_CHAR(U.REG_DATE, 'YYYY-MM-DD') = #{date}
AND ( UPPER(U.ID) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.EMAIL) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.NICKNAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.PROVIDER) LIKE '%' || UPPER(#{keyword}) || '%' )
ORDER BY U.USER_NO DESC OFFSET #{offset} ROWS FETCH NEXT 20 ROWS ONLY
